import test from 'node:test';
import assert from 'node:assert/strict';
import {spawn} from 'node:child_process';
import {fileURLToPath} from 'node:url';
import {mkdtemp,rm,access,writeFile} from 'node:fs/promises';
import {tmpdir} from 'node:os';
import {insightScenario} from '../../server/test/insight-helpers.js';
const executable=fileURLToPath(new URL('../bin/crew.js',import.meta.url));
function cli(s,token,args) {
  return new Promise((resolve,reject)=>{
    const child=spawn(process.execPath,[executable,...args,'--url',s.server.url,'--token',token,'--json']);
    let stdout='',stderr='',expired=false;
    const timer=setTimeout(()=>{expired=true;child.kill('SIGKILL');},8000);
    child.stdout.on('data',chunk=>stdout+=chunk);child.stderr.on('data',chunk=>stderr+=chunk);
    child.on('error',error=>{clearTimeout(timer);reject(error);});
    child.on('close',code=>{clearTimeout(timer);if(expired)reject(new Error('CLI boundary deadline'));else resolve({code,stdout,stderr});});
  });
}
async function issueToken(s,scopes,actor=s.api){return (await actor('POST','/tokens',{name:'CLI boundary',scopes})).data;}

test('real CLI preserves useful work reads but denies every insight command family without insight scopes',()=>insightScenario(async s=>{
  const token=(await issueToken(s,['project:read','org:read'])).token;
  const positive=await cli(s,token,['project','show',s.project.id]);assert.equal(positive.code,0,positive.stderr);assert.equal(JSON.parse(positive.stdout).project.id,s.project.id);
  for(const args of [['search','--org',s.org.id],['feed','list','--org',s.org.id],['inbox','list','--org',s.org.id],['filter','list','--org',s.org.id],['dashboard','--org',s.org.id]]) {
    const denied=await cli(s,token,args);assert.equal(denied.code,1,args.join(' '));assert.match(denied.stderr,/scope|FORBIDDEN/i);assert(!denied.stdout.includes(s.issue.title));
  }
}));

test('real CLI guest export denial leaves no output and scoped import preview cannot mutate destination',()=>insightScenario(async s=>{
  const directory=await mkdtemp(tmpdir()+'/crew-people-boundary-');
  try {
    const hidden=(await s.api('POST','/orgs/'+s.org.id+'/projects',{key:'HID',name:'Private CLI'})).data.project;
    await s.api('POST','/projects/'+hidden.id+'/issues',{title:'Hidden CLI content'});
    await s.api('PATCH','/orgs/'+s.org.id+'/members/'+s.memberUser.id,{role:'guest'});
    await s.api('POST','/projects/'+s.project.id+'/guests',{userId:s.memberUser.id});
    const guestToken=(await issueToken(s,['*'],s.member)).token;
    const visible=await cli(s,guestToken,['search','--org',s.org.id]);assert.equal(visible.code,0,visible.stderr);assert.equal(JSON.parse(visible.stdout).total,1);assert(!visible.stdout.includes('Hidden CLI content'));
    const output=directory+'/denied.json',denied=await cli(s,guestToken,['export',hidden.id,'--output',output]);
    assert.equal(denied.code,1);assert.match(denied.stderr,/permission|FORBIDDEN/i);await assert.rejects(access(output),{code:'ENOENT'});
    const document=(await s.api('GET','/projects/'+s.project.id+'/export')).data;
    const filename=directory+'/input.json';await writeFile(filename,JSON.stringify(document));
    const scoped=(await issueToken(s,['import:write','issue:write','comment:write'])).token;
    const result=await cli(s,scoped,['import','--org',s.org.id,'--file',filename,'--key','DENY','--preview']);
    assert.equal(result.code,1);assert.match(result.stderr,/scope|FORBIDDEN/i);
    assert.equal(s.server.ctx.db.prepare("SELECT count(*) n FROM projects WHERE key='DENY'").get().n,0);
  } finally {await rm(directory,{recursive:true,force:true});}
}));

test('real CLI search immediately denies a revoked credential after a successful authorized search',()=>insightScenario(async s=>{
  const issued=await issueToken(s,['org:read','insight:read']);
  const positive=await cli(s,issued.token,['search','--org',s.org.id]);assert.equal(positive.code,0,positive.stderr);assert.equal(JSON.parse(positive.stdout).items[0].id,s.issue.id);
  await s.api('DELETE','/tokens/'+issued.personalToken.id);
  const denied=await cli(s,issued.token,['search','--org',s.org.id]);assert.equal(denied.code,1);assert.match(denied.stderr,/UNAUTHENTICATED|sign in/i);assert(!denied.stdout.includes(s.issue.title));
}));
